"""Original FCC foundation exercises and the attributed QuranEnc reading interface."""
from html import escape as e
import json

def item(title,urdu,body,examples,practice,reference=None):
 return dict(title=title,urdu=urdu,body=body,examples=examples,practice=practice,reference=reference)
QAIDA=[
 item('Meet the letters','حروف کی پہچان','Read from right to left. Notice the main shape and the number and position of dots. Learn a letter’s name first, then practise its sound with your teacher.', [('ا','Alif'),('ب','Baa'),('ت','Taa'),('ث','Thaa'),('ج','Jeem'),('ح','Haa'),('خ','Khaa'),('د','Daal'),('ذ','Dhaal'),('ر','Raa'),('ز','Zaay'),('س','Seen'),('ش','Sheen'),('ص','Saad'),('ض','Daad'),('ط','Taa'),('ظ','Zaa'),('ع','Ayn'),('غ','Ghayn'),('ف','Faa'),('ق','Qaaf'),('ك','Kaaf'),('ل','Laam'),('م','Meem'),('ن','Noon'),('ه','Haa'),('و','Waaw'),('ي','Yaa'),('ء','Hamzah')], 'Point to baa, taa and thaa. What changes between their shapes? Say each name with a teacher.'),
 item('Look at joined shapes','ملے ہوئے حروف','Most letters change shape when joined. Read the letters in each group from right to left. Alif, daal, dhaal, raa, zaay and waaw do not connect to the following letter on their left.', [('ب','Separate baa'),('بـ','Initial baa'),('ـبـ','Middle baa'),('ـب','Final baa'),('بت','Baa + taa'),('تم','Taa + meem'),('لم','Laam + meem'),('من','Meem + noon')], 'Trace the baa shapes. Find the dot below in every position. These are letter combinations for practice.'),
 item('Fathah · short a','زبر','Fathah is the small stroke above a letter. It gives a short “a” vowel. Keep the sound short; do not turn it into a long vowel.', [('بَ','ba'),('تَ','ta'),('جَ','ja'),('دَ','da'),('سَ','sa'),('مَ','ma')], 'Read the six combinations slowly. Ask your teacher to check the letter sound and the short vowel.'),
 item('Kasrah · short i','زیر','Kasrah is the small stroke below a letter. It gives a short “i” vowel. Compare the same letter with fathah and kasrah.', [('بِ','bi'),('تِ','ti'),('جِ','ji'),('دِ','di'),('سِ','si'),('مِ','mi')], 'Alternate بَ and بِ. Keep the consonant the same while changing only the vowel.'),
 item('Dammah · short u','پیش','Dammah is the small curled mark above a letter. It gives a short “u” vowel. Practise a clear short sound rather than stretching it.', [('بُ','bu'),('تُ','tu'),('جُ','ju'),('دُ','du'),('سُ','su'),('مُ','mu')], 'Read بَ بِ بُ, then مَ مِ مُ. Your teacher can model each sound before you repeat.'),
 item('Tanween','تنوین','Tanween uses doubled vowel marks and adds a final noon sound in connected reading: an, in or un. Stopping at the end of a word has additional rules; practise those with a teacher.', [('بً','ban'),('بٍ','bin'),('بٌ','bun'),('تً','tan'),('تٍ','tin'),('تٌ','tun')], 'Compare a single vowel with its doubled mark. Listen for the added noon sound. These are sound drills, not Quran verses.'),
 item('Sukoon and blending','سکون','Sukoon marks a letter without its own vowel. Join it to the sound before it without adding an extra vowel. The mouth position matters as much as the written mark.', [('بَتْ','bat'),('مِنْ','min'),('قُلْ','qul'),('لَمْ','lam')], 'Identify the letter carrying sukoon, then blend the combination as one unit. Ask a teacher to check the final consonant.'),
 item('Madd · long vowels','مد','A basic long vowel is held for two counts. Alif follows fathah; a saakin waaw follows dammah; a saakin yaa follows kasrah. Other madd rules depend on what follows.', [('بَا','baa'),('بُو','boo'),('بِي','bee'),('تَا','taa'),('تُو','too'),('تِي','tee')], 'Compare بَ with بَا. Keep an even two-count length for the basic long vowel.'),
 item('Shaddah and revision','تشدید اور دہرائی','Shaddah marks a doubled consonant: the first part closes the preceding sound and the second part carries the written vowel. Noon and meem with shaddah also have ghunnah, taught in Tajweed.', [('بَّ','Doubled baa'),('تَّ','Doubled taa'),('رَّ','Doubled raa'),('مَّ','Meem with shaddah'),('نَّ','Noon with shaddah')], 'Name the marks in بَ بِ بُ بْ بَّ. Revisit any mark you cannot yet identify, then move to short Quran passages with your teacher.',(1,1))]
TAJWEED=[
 item('Makharij · where sounds begin','مخارج','Articulation is the place where a letter’s sound is formed. Begin with the throat, tongue and lips, and let a teacher demonstrate differences that transliteration cannot represent.', [('ء ه','Throat-letter practice'),('ع ح','Throat-letter practice'),('غ خ','Throat-letter practice'),('ب م','Lip-letter comparison'),('ق ك','Back-of-tongue comparison')], 'Listen to one pair, repeat it, then ask your teacher to check the sound. A written guide cannot assess pronunciation.'),
 item('Ghunnah','غنہ','Ghunnah is a nasal sound. A noon or meem carrying shaddah is held with ghunnah for two counts. Keep the sound steady rather than adding a separate vowel.', [('نّ','Noon mushaddadah'),('مّ','Meem mushaddadah')], 'Find the doubled noon or meem in your reading. Let a teacher model two even counts.'),
 item('Izhar · pronounce clearly','اظہار','For noon saakin or tanween followed by one of the six throat letters, pronounce the noon sound clearly. Keep the following letter distinct.', [('ء ه ع ح غ خ','Six izhar letters'),('نْ + ء','Noon saakin + hamzah'),('نْ + ع','Noon saakin + ayn')], 'Identify the letter after noon saakin. If it is a throat letter, practise a clear separation with your teacher.'),
 item('Idgham · merge sounds','ادغام','In the usual cross-word rule, noon saakin or tanween merges into a following ي ن م و ل ر. With ي ن م و there is ghunnah; with ل ر there is no ghunnah. There are exceptions, including certain within-word combinations.', [('ي ن م و','With ghunnah'),('ل ر','Without ghunnah'),('نْ + م','Cross-word letter drill')], 'Sort the six letters into the two groups. Ask your teacher to demonstrate the difference in connected reading.'),
 item('Iqlab · change the sound','اقلاب','When noon saakin or tanween is followed by baa, the noon sound changes to a concealed meem sound with ghunnah. In many mushafs a small meem helps mark the rule.', [('نْ + ب','Noon saakin before baa'),('ب','The iqlab trigger letter')], 'Spot baa after noon saakin or tanween. Practise the transition slowly with a teacher rather than pronouncing a full clear noon.'),
 item('Ikhfa · conceal the noon','اخفاء','For the remaining fifteen letters, noon saakin or tanween is concealed with ghunnah. The tongue prepares for the next letter; the sound is between clear izhar and full merging.', [('ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك','Fifteen ikhfa letters')], 'Choose one trigger letter and ask your teacher to model it. Repeat without making a complete clear noon or doubling the next consonant.'),
 item('Qalqalah','قلقلہ','When one of ق ط ب ج د is saakin, including when stopping makes it saakin, release the consonant with a controlled echo. Do not add a new vowel after it.', [('ق ط ب ج د','Qalqalah letters'),('قْ','Qaaf with sukoon'),('طْ','Taa with sukoon'),('بْ','Baa with sukoon')], 'Name the five letters, then compare a saakin letter with a vowelled letter under a teacher’s guidance.'),
 item('Madd and stopping','مد اور وقف','Basic madd is two counts. Longer madd depends on its cause and the reading being followed. Stopping signs guide where to pause; breath, word endings and meaning also need guided practice.', [('ا و ي','Basic madd letters'),('مـ','Compulsory-stop sign'),('لا','Do not deliberately stop here'),('ج','Permissible-stop sign')], 'Read a short passage with your teacher. Mark a suitable stopping point and check what happens to the last sound.',(112,1))]
STUDIES=[
 item('Belief and sincerity','ایمان اور اخلاص','Begin by learning about Allah’s oneness and the meaning of worship. Read Surah Al-Ikhlas with its English translation, then discuss its message with your teacher.', [], 'Read the complete short surah. In your own words, explain one thing you learned without replacing the published translation.',(112,1)),
 item('Cleanliness and wudu','پاکیزگی اور وضو','Learn why cleanliness matters before prayer. Read the Quranic passage about purification, then ask your teacher to demonstrate the steps of wudu and explain the practice followed in your family.', [], 'Describe the steps you observed. Ask about anything you are unsure of, including what to do when water cannot be used.',(5,6)),
 item('Salah and a daily routine','نماز اور روزمرہ معمول','Learn the names of the five daily prayers, prepare a calm place and ask your teacher to demonstrate the movements and recitations. Build understanding alongside a consistent routine.', [('Fajr','Dawn'),('Dhuhr','After midday'),('Asr','Afternoon'),('Maghrib','After sunset'),('Isha','Night')], 'Name the five prayers in order. Use a reliable local timetable with your family; prayer times depend on location and date.',(2,43)),
 item('Quranic duas','قرآنی دعائیں','Read a supplication for knowledge and a supplication for good in this life and the next directly from the Quran reader. Keep the Arabic and the published English meaning together.', [], 'Open Surah Ta-Ha 20:114. Also read Al-Baqarah 2:201 using the surah and ayah controls. Ask your teacher to help with pronunciation.',(20,114)),
 item('Kindness and respect','حسن اخلاق','Practise respectful speech, avoid hurtful labels and listen before replying. Read the Quranic reference, then discuss an everyday situation where your words can help someone.', [], 'Describe a kind response to a classmate who makes a mistake. Choose one practical action for this week.',(49,11)),
 item('Parents and gratitude','والدین اور شکرگزاری','Learn to express gratitude to Allah and appreciation for parents. Read the referenced ayah with its translation and discuss age-appropriate ways to show care at home.', [], 'Choose one helpful task and one way to thank a parent or caregiver. Discuss the passage with your teacher.',(31,14))]

COURSES={'noorani-qaida':('FOUNDATIONS WORKBOOK','Start with a letter. Build a reading habit.','نورانی قاعدہ کی بنیادی مشقیں',QAIDA),'tajweed':('RULES & GUIDED PRACTICE','Notice the rule. Practise the sound.','تجوید اور مخارج',TAJWEED),'islamic-studies':('READ · REFLECT · PRACTISE','Small lessons for everyday understanding.','بنیادی اسلامی تعلیم',STUDIES)}

def source_link(reference):
 s,a=reference
 return f'<a class="btn secondary" href="/quran-reading/?surah={s}&amp;ayah={a}#quran-reader">Read Quran {s}:{a}</a> <a class="btn secondary" href="/quran-translation/#english-translation">Open English translation</a>'

def workbook(slug):
 kicker,title,urdu,lessons=COURSES[slug]
 nav=''.join(f'<a class="learning-step" href="#lesson-{i+1}" data-lesson-select="{i}" aria-current="{("step" if i==0 else "false")}"><span>{i+1:02}</span><div>{e(l["title"])}</div></a>' for i,l in enumerate(lessons))
 panels=[]
 for i,l in enumerate(lessons):
  examples=''.join(f'<div class="sound-tile"><span class="sound-arabic" dir="rtl" lang="ar">{e(ar)}</span><small>{e(en)}</small></div>' for ar,en in l['examples'])
  if slug=='islamic-studies':examples=examples.replace('class="sound-arabic" dir="rtl" lang="ar"','class="study-term"')
  panels.append(f'<article class="learning-lesson" id="lesson-{i+1}" data-learning-lesson="{i}" aria-labelledby="lesson-title-{i+1}"><span class="card-kicker">LESSON {i+1:02} OF {len(lessons):02}</span><h3 id="lesson-title-{i+1}" tabindex="-1">{e(l["title"])}</h3><p class="learning-explanation">{e(l["body"])}</p>{("<div class=sound-grid>"+examples+"</div>") if examples else ""}<div class="learning-practice"><span class="eyebrow">YOUR PRACTICE</span><h4>Try it with your teacher.</h4><p>{e(l["practice"])}</p></div>{source_link(l["reference"]) if l["reference"] else ""}</article>')
 sources='<a href="https://darulquran.co.uk/quranic-articles/learn-tajwid/what-is-tajweed-in-quran/" target="_blank" rel="noopener">Further reading: DarulQuran Tajweed overview</a>' if slug=='tajweed' else '<a href="/quran-translation/">Explore the English Quran translation</a>'
 return f'''<section class="shell section quran-library" id="learning-library"><div class="section-head"><span class="eyebrow">{kicker}</span><h2>{title}</h2><p>Choose a lesson to open its explanation and practice. Work at your own pace, then revisit it with your teacher.</p></div><div class="learning-workspace" data-learning-workbook><nav class="learning-steps" aria-label="{e(slug)} lessons">{nav}</nav><div class="learning-desk"><div class="learning-progress"><span data-learning-progress>Lesson 1 of {len(lessons)}</span><span>READ · TRY · REVISIT</span></div>{''.join(panels)}<div class="learning-pagination" data-learning-controls hidden><button type="button" class="btn secondary" data-learning-prev disabled>Previous lesson</button><button type="button" class="btn primary" data-learning-next>Next lesson</button></div></div></div><div class="learning-source"><strong>About these lessons</strong><p>Original Future Cloud Campus foundation exercises, not a reproduction of a published Qaida book or a complete certification course. Letter drills are practice combinations, not Quran quotations. A qualified teacher should model and check pronunciation.</p>{sources}</div></section>'''

def reader(assets):
 index=json.loads((assets/'quran/index.json').read_text())
 options=''.join(f'<option value="{c["number"]}">{c["number"]}. {e(c["name"])}</option>' for c in index['chapters'])
 return f'''<section class="shell section quran-library" id="quran-reader"><div class="reader-heading"><div class="section-head"><span class="eyebrow">QURAN NAZRA · ARABIC READING</span><h2>Read. Understand. Return.</h2><p>All 114 surahs in Arabic, with English controls. Choose a surah and ayah to practise Nazra. <a href="/quran-translation/#english-translation">Read the English translation</a> in its separate resource. Urdu translation is optional below.</p></div><div class="reader-seal" aria-hidden="true">اقرأ</div></div><div class="quran-reader" data-quran-reader data-quran-version="{e(index['version'])}"><form class="reader-toolbar" data-reader-form><label>Surah<select data-reader-surah aria-label="Select surah">{options}</select></label><label>Ayah<input type="number" min="1" max="7" value="1" data-reader-ayah aria-label="Go to ayah number" required></label><button class="btn primary" type="submit">Open ayah</button></form><div class="reader-tools"><label class="reader-toggle"><input type="checkbox" data-reader-translation>Optional: show Urdu translation</label><div class="reader-font-tools" aria-label="Arabic text size"><button type="button" class="btn secondary" data-reader-smaller aria-label="Decrease Arabic text size">A−</button><span data-reader-size>32px</span><button type="button" class="btn secondary" data-reader-larger aria-label="Increase Arabic text size">A+</button></div><button class="btn secondary" type="button" data-reader-resume hidden>Resume saved ayah</button></div><p class="reader-status" data-reader-status role="status" aria-live="polite">Preparing the Quran reader…</p><div class="reader-error" data-reader-error hidden><p data-reader-error-copy></p><button type="button" class="btn secondary" data-reader-retry>Try again</button> <a href="https://quranenc.com/en/browse/urdu_junagarhi" target="_blank" rel="noopener">Read on QuranEnc.com</a></div><div class="reader-surah-heading"><span data-reader-title>Al-Fatihah</span><span data-reader-count>7 ayahs</span></div><div class="reader-verses" data-reader-verses aria-busy="true"></div><div class="reader-page-controls"><button class="btn secondary" type="button" data-reader-prev disabled>Previous ayahs</button><span data-reader-page></span><button class="btn primary" type="button" data-reader-next disabled>Next ayahs</button></div><div class="reader-surah-controls"><button type="button" class="text-link" data-reader-prev-surah disabled>Previous surah</button><button type="button" class="text-link" data-reader-next-surah>Next surah</button></div></div><aside class="reader-attribution"><strong>Arabic text &amp; optional Urdu translation</strong><p>Optional Urdu translation (off by default): Muhammad Ibrahim Junagarhi. Developed under the supervision of the Rowwad Translation Center. Source: <a href="https://quranenc.com/en/browse/urdu_junagarhi" target="_blank" rel="noopener">QuranEnc.com</a> · version {e(index['version'])}. Arabic: KFGQPC Uthmanic Hafs v20 with its matched font. Arabic, translation and footnotes are presented unchanged; a translation conveys meanings and is distinct from the Arabic Quran.</p><details><summary>Source information and reporting a correction</summary><p>{e(index['description'])}</p><p>Imported {e(index['imported_at'][:10])}. For observations on the translation, use the feedback option on <a href="https://quranenc.com/en/browse/urdu_junagarhi" target="_blank" rel="noopener">the publisher’s source page</a>. <a href="https://quranenc.com/en/home/api/" target="_blank" rel="noopener">Publisher terms and API information</a>.</p><p>Saved reading positions stay in this browser. This reader does not assess recitation or provide a religious ruling.</p></details></aside><noscript><p>Enable JavaScript to use the reader, or <a href="https://quranenc.com/en/browse/urdu_junagarhi">read the complete translation on QuranEnc.com</a>.</p></noscript></section>'''

def hub():
 return '''<section class="shell section learning-hub"><div class="section-head"><span class="eyebrow">ENGLISH LEARNING · ARABIC READING</span><h2>Your next step, clearly laid out.</h2><p>Choose Translation, Noorani Qaida, Quran Nazra or Islamic Studies. Every course has a separate learning space and its own resources. Tajweed offers extra guided recitation practice.</p></div><div class="learning-hub-links"><a class="btn primary" href="/quran-translation/#english-translation">English Translation</a><a class="btn secondary" href="/noorani-qaida/#course-resources">Noorani Qaida</a><a class="btn secondary" href="/quran-reading/#quran-reader">Quran Nazra</a><a class="btn secondary" href="/islamic-studies/#course-resources">Islamic Studies</a><a class="btn secondary" href="#resource-collections">All supplied collections</a></div></section>'''
